import java.util.*;

class Solution {
  public int mostBooked(int n, int[][] meetings) {
    Arrays.sort(meetings, Comparator.comparingInt(a -> a[0]));
    PriorityQueue<Integer> available = new PriorityQueue<>();
    for (int room = 0; room < n; room++) available.offer(room);
    PriorityQueue<long[]> busy =
        new PriorityQueue<>(
            (a, b) -> a[0] == b[0] ? Long.compare(a[1], b[1]) : Long.compare(a[0], b[0]));
    int[] used = new int[n];
    for (int[] meeting : meetings) {
      long start = meeting[0];
      long duration = meeting[1] - meeting[0];
      while (!busy.isEmpty() && busy.peek()[0] <= start) available.offer((int) busy.poll()[1]);
      long actualStart = start;
      if (available.isEmpty()) {
        long[] first = busy.poll();
        actualStart = first[0];
        available.offer((int) first[1]);
        while (!busy.isEmpty() && busy.peek()[0] == actualStart)
          available.offer((int) busy.poll()[1]);
      }
      int room = available.poll();
      busy.offer(new long[] {actualStart + duration, room});
      used[room]++;
    }
    int answer = 0;
    for (int room = 1; room < n; room++) if (used[room] > used[answer]) answer = room;
    return answer;
  }
}
